const statsRows = $('Load Stats History').all().map(r => r.json);
const listingRows = $('Load Listing Data').all().map(r => r.json);

// Sort stats by week descending
statsRows.sort((a, b) => new Date(b.week_ending) - new Date(a.week_ending));

const thisWeek = statsRows[0] || {};
const lastWeek = statsRows[1] || {};
const fourWeeksAgo = statsRows[3] || {};

function pct(a, b) {
  if (!b || b === 0) return null;
  return parseFloat(((a - b) / b * 100).toFixed(1));
}

const revenue = parseFloat(thisWeek.revenue) || 0;
const orders = parseInt(thisWeek.orders) || 0;
const views = parseInt(thisWeek.views) || 0;
const visits = parseInt(thisWeek.visits) || 0;
const favorites = parseInt(thisWeek.favorites) || 0;
const conversionRate = visits > 0 ? parseFloat((orders / visits * 100).toFixed(2)) : 0;
const avgOrderValue = orders > 0 ? parseFloat((revenue / orders).toFixed(2)) : 0;

const lastRevenue = parseFloat(lastWeek.revenue) || 0;
const lastOrders = parseInt(lastWeek.orders) || 0;
const lastViews = parseInt(lastWeek.views) || 0;
const lastVisits = parseInt(lastWeek.visits) || 0;
const lastConversion = lastVisits > 0 ? parseFloat((lastOrders / lastVisits * 100).toFixed(2)) : 0;

// 4-week averages
const recent4 = statsRows.slice(0, 4);
const avg4Revenue = recent4.reduce((s, r) => s + (parseFloat(r.revenue) || 0), 0) / Math.max(recent4.length, 1);
const avg4Orders = recent4.reduce((s, r) => s + (parseInt(r.orders) || 0), 0) / Math.max(recent4.length, 1);

// Top listings by views this week
const topListings = listingRows
  .filter(l => l.listing_title)
  .sort((a, b) => (parseInt(b.views_this_week) || 0) - (parseInt(a.views_this_week) || 0))
  .slice(0, 5)
  .map(l => ({
    title: l.listing_title,
    views: parseInt(l.views_this_week) || 0,
    orders: parseInt(l.orders_this_week) || 0,
    price: parseFloat(l.price) || 0,
    conversion: (parseInt(l.views_this_week) || 0) > 0
      ? parseFloat(((parseInt(l.orders_this_week)||0) / (parseInt(l.views_this_week)||0) * 100).toFixed(1))
      : 0,
    daysListed: parseInt(l.days_listed) || 0
  }));

// Listings with high views but zero orders (conversion problem)
const coldListings = listingRows
  .filter(l => l.listing_title && (parseInt(l.views_this_week) || 0) > 20 && (parseInt(l.orders_this_week) || 0) === 0)
  .map(l => ({ title: l.listing_title, views: parseInt(l.views_this_week) || 0, price: parseFloat(l.price) || 0 }));

const weekOf = thisWeek.week_ending || new Date().toISOString().split('T')[0];

return [{
  json: {
    weekOf,
    current: { revenue, orders, views, visits, favorites, conversionRate, avgOrderValue },
    vsLastWeek: {
      revenue: pct(revenue, lastRevenue),
      orders: pct(orders, lastOrders),
      views: pct(views, lastViews),
      visits: pct(visits, lastVisits),
      conversion: pct(conversionRate, lastConversion)
    },
    avg4: { revenue: parseFloat(avg4Revenue.toFixed(2)), orders: parseFloat(avg4Orders.toFixed(1)) },
    topListings,
    coldListings,
    totalListings: listingRows.filter(l => l.listing_title).length,
    shopName: $env.SHOP_NAME || 'Your Etsy Shop'
  }
}];

