const body = $input.first().json.body;
const required = ['week_ending', 'revenue', 'orders', 'visits', 'views'];
const missing = required.filter(f => body[f] === undefined);
if (missing.length) {
  return [{ json: { valid: false, error: `Missing: ${missing.join(', ')}` } }];
}
return [{ json: { valid: true, ...body } }];
